        claim.setCorrectsDate(correctsDate);
        claim.setRef(input.ref());
        claim.setTags(input.tags());
        claim.setLateEntry(periods.isSoftClosedOn(sheet.getId(), dueBy));
        claim.fixDue(date, terms, holidays.datesOf(sheet.getId()));
        return claim;
    }

